{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PARTIAL",
      "chunk_id": "text_4",
      "quote": "Background: Mesenchymal stem/stromal cells (MSCs) and their secreted products are a promising therapy for COVID-19 given their immunomodulatory and tissue repair capabilities. Many small studies were launched at the onset of the pandemic, and repeated meta-analysis is critical to obtain timely and suf fi cient statistical power to determine ef fi cacy.",
      "reason": "The evidence states the current knowledge (MSCs/secreted products are promising; many small studies exist) but does not clearly describe “important uncertainties” beyond the need for statistical power."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "Many small studies were launched at the onset of the pandemic, and repeated meta-analysis is critical to obtain timely and suf fi cient statistical power to determine ef fi cacy.",
      "reason": "The importance/need for conducting the review is explicitly explained (repeated meta-analysis is critical for timely, sufficient power to determine efficacy)."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence was retrieved that cites or discusses previous similar systematic reviews or explains why a new/updated review is needed in relation to them."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "PRESENT",
      "chunk_id": "text_26",
      "quote": "Thus, the pleiotropic anti-in fl ammatory and regenerative effects of MSCs may point to several potential mechanisms by which MSCs exert their apparent bene fi cial effect.",
      "reason": "The evidence describes hypothesised mechanisms of how MSCs may benefit COVID-19 (anti-inflammatory and regenerative effects), consistent with briefly describing a proposed mechanism of action."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "There is no retrieved evidence of a logic model to show hypothesised relationships between intervention components and outcomes."
    }
  ],
  "confidence": 62
}

