{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_9",
      "quote": "All English-language, full-text, clinical studies examining the use of MSCs or their secretome (MSC-EVs, MSC-CM) as a therapeutic intervention for COVID-19 were included. Studies could be single armed (uncontrolled) or have a comparator or control groups (controlled). For the controlled studies, all randomization methods were considered acceptable (randomized, pseudo-randomized, and nonrandomized). Studies published in languages other than English, review articles, commentaries, editorials, letters, case reports, conference abstracts, unpublished gray literature and other study types (in vitro studies, preclinical animal studies, etc. ) were excluded.",
      "reason": "Included/excluded study design characteristics (clinical studies; single-arm vs controlled; acceptable randomization methods) and other eligibility characteristics (population infection, tissue sources, routes, acceptability of MSC-EVs/secretome) are specified, but eligibility details on follow-up requirements and relevant question-framework components (e.g., specific follow-up/time horizon) are not explicitly reported in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_9",
      "quote": "All English-language, full-text, clinical studies examining the use of MSCs or their secretome (MSC-EVs, MSC-CM) as a therapeutic intervention for COVID-19 were included.",
      "reason": "Report characteristics are partially specified (English-language and full-text inclusion; non-English excluded). However, the dissemination year and publication/report status (beyond full-text and types excluded) are not explicitly described in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No retrieved evidence explains whether exclusions were distinguished as being due to outcomes not being measured versus outcomes not being reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_13",
      "quote": "For dichotomous outcomes, risk ratios (RRs) were calculated to determine the risk of death between the control and experimental groups at study endpoint. For continuous outcomes, the standardized mean difference (SMD) between control and experimental groups was calculated using random effects meta-analyses.",
      "reason": "The retrieved evidence identifies “control” and “experimental” groups used for pooling outcomes and indicates comparisons between them. However, it does not explicitly describe the groups used in each synthesis or link these group definitions to specific comparisons defined in the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence states eligibility restrictions (e.g., English-language/full-text; exclusion of certain study types), but it does not provide rationales for notable restrictions."
    }
  ],
  "confidence": 62
}

